// Parse the input from the previous node
const input = $input.all();

let allJobs = [];

// Process each item in the input array
for (const item of input) {
  try {
    let parsedData = null;
    const jsonData = item.json;

    // Handle different response structures
    if (Array.isArray(jsonData)) {
      // If it's an array, process each element
      for (const element of jsonData) {
        if (element.text) {
          const trimmedText = element.text.trim();

          // Skip empty responses
          if (trimmedText === '[]' || trimmedText === '') {
            continue;
          }

          // Remove markdown code blocks if present
          let cleanText = trimmedText;
          if (cleanText.startsWith('```json')) {
            cleanText = cleanText.replace(/```json\n?/g, '').replace(/```\n?/g, '');
          } else if (cleanText.startsWith('```')) {
            cleanText = cleanText.replace(/```\n?/g, '');
          }

          cleanText = cleanText.trim();

          // Skip if still empty
          if (cleanText === '[]' || cleanText === '') {
            continue;
          }

          try {
            parsedData = JSON.parse(cleanText);

            // If it's an array, add all jobs
            if (Array.isArray(parsedData)) {
              allJobs.push(...parsedData);
            }
          } catch (parseError) {
            console.error('Failed to parse text:', cleanText.substring(0, 100));
            console.error('Parse error:', parseError.message);
          }
        }
      }
    } else if (jsonData.text) {
      // Handle single text response
      const trimmedText = jsonData.text.trim();

      if (trimmedText !== '[]' && trimmedText !== '') {
        let cleanText = trimmedText;
        if (cleanText.startsWith('```json')) {
          cleanText = cleanText.replace(/```json\n?/g, '').replace(/```\n?/g, '');
        } else if (cleanText.startsWith('```')) {
          cleanText = cleanText.replace(/```\n?/g, '');
        }

        cleanText = cleanText.trim();

        if (cleanText !== '[]' && cleanText !== '') {
          try {
            parsedData = JSON.parse(cleanText);
            if (Array.isArray(parsedData)) {
              allJobs.push(...parsedData);
            }
          } catch (parseError) {
            console.error('Failed to parse text:', cleanText.substring(0, 100));
          }
        }
      }
    }
  } catch (error) {
    console.error('Error processing item:', error.message);
  }
}

console.log(`Total jobs collected: ${allJobs.length}`);

// If no jobs found, return empty result
if (allJobs.length === 0) {
  console.log('No jobs found in any of the responses');
  return [{
    json: {
      message: 'No jobs found in the responses',
      totalJobs: 0,
      jobsWithEmails: 0
    }
  }];
}

// Filter for jobs with emails
const jobsWithEmails = allJobs.filter(job => 
  job.Emails && job.Emails.trim() !== ''
);

console.log(`Found ${jobsWithEmails.length} jobs with emails out of ${allJobs.length} total`);

// Prepare bulk array for webhook according to your DTO
const bulkJobsArray = jobsWithEmails.map(job => ({
  jobTitle: job.JobTitle || 'N/A',
  company: job.Company || 'N/A',
  location: job.Location || '',
  emails: job.Emails || '',
  emailType: job.EmailType || 'summary',
  isRemote: job.IsRemote || false,
  salary: job.Salary || '',
  link: job.Link || '',
  snippet: (job.Snippet || '').substring(0, 500), // Match DTO max length
  scrapedDate: job.ScrapedDate || null,
  secretToken: '046801ecc26b566bb35515f48bfb775ef2d909ca2e78e667613b4cdcf65fc831'
}));

// Return results
if (bulkJobsArray.length === 0) {
  console.log('No jobs with emails found');
  return [{
    json: {
      message: 'No jobs with emails found',
      totalJobs: allJobs.length,
      jobsWithEmails: 0
    }
  }];
}

console.log(`Prepared ${bulkJobsArray.length} jobs for webhook submission`);

// Return the bulk jobs array
return [{
  json: {
    jobs: bulkJobsArray,
    metadata: {
      totalProcessed: allJobs.length,
      jobsWithEmails: bulkJobsArray.length,
      processedAt: new Date().toISOString()
    }
  }
}];
